import{_ as r}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/OFF.BrU7kQE-.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as i}from"./chunks/M-S-SW8c.OZF8VB_x.js";import{_ as o,o as n,c as s,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const w=JSON.parse('{"title":"Smartwatch","description":"","frontmatter":{"source_hash":"3b41debaf8","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/smartwatch/smartwatch.md","filePath":"it/smartwatch/smartwatch.md"}'),c={name:"it/smartwatch/smartwatch.md"};function d(p,a,m,h,b,u){return n(),s("div",null,[...a[0]||(a[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+r+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Caratteristiche Collegamenti Smart Watch</p></div><h2 id="xdrip-direct-integration" tabindex="-1">Integrazione diretta in xDrip <a class="header-anchor" href="#xdrip-direct-integration" aria-label="Permalink to &quot;Integrazione diretta in xDrip {#xdrip-direct-integration}&quot;">​</a></h2><p>xDrip supporta un&#39;ampia gamma di smartwatch.</p><h3 id="android-wear-integration" tabindex="-1"><a href="./wear.html">Integrazione Android Wear</a> <a class="header-anchor" href="#android-wear-integration" aria-label="Permalink to &quot;[Integrazione Android Wear](./wear) {#android-wear-integration}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Integrazione Android Wear</p></div><p>L&#39;integrazione più completa la trovi sugli orologi Wear OS, perché eseguono localmente una parte dell&#39;app xDrip.</p><p>L&#39;estensione wear di xDrip non è più in sviluppo.</p><p>Se ti servono altri quadranti o personalizzazioni puoi usare <a href="https://github.com/FreDiabetics/xDrip--Tasker-Tizen-Watchface-Integration/blob/master/README.md" target="_blank" rel="noreferrer">Tasker</a> (ma non come collector autonomo).</p><h3 id="pebble-integration" tabindex="-1"><a href="./pebble.html">Integrazione Pebble</a> <a class="header-anchor" href="#pebble-integration" aria-label="Permalink to &quot;[Integrazione Pebble](./pebble) {#pebble-integration}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Integrazione Pebble</p></div><p>L&#39;uso dello smartwatch Pebble è una tappa storica di CGM in the Cloud. Gli orologi Pebble originali sono stati dismessi nel 2016, quando Pebble è stata acquistata da Fitbit (le sue risorse sono state spostate negli archivi e su <a href="https://rebble.io/" target="_blank" rel="noreferrer">rebble.io</a>). Nel 2025 sono stati rilanciati nuovi modelli Pebble: xDrip li supporta entrambi, vedi <a href="./pebble.html">Integrazione Pebble</a>.</p><h3 id="amazfit-sync-service" tabindex="-1"><a href="https://crazyinfo.de/2018/07/25/xdrip-smartwatch-widget-fuer-amazfit-pace-stratos/" target="_blank" rel="noreferrer">Servizio di sincronizzazione AmazFit</a> <a class="header-anchor" href="#amazfit-sync-service" aria-label="Permalink to &quot;[Servizio di sincronizzazione AmazFit](https://crazyinfo.de/2018/07/25/xdrip-smartwatch-widget-fuer-amazfit-pace-stratos/) {#amazfit-sync-service}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Servizio di sincronizzazione AmazFit</p></div><p>AmazFit era usato solo per i modelli Pace e Stratos.<br><strong>Non puoi usare questa funzione con altri orologi AmazFit.</strong></p><h3 id="bluejay-watch" tabindex="-1"><a href="./bluejay.html">BlueJay Watch</a> <a class="header-anchor" href="#bluejay-watch" aria-label="Permalink to &quot;[BlueJay Watch](./bluejay) {#bluejay-watch}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch</p></div><p>BlueJay è un compagno straordinario per il tuo sensore Dexcom, con o senza xDrip, con o senza telefono.</p><h3 id="lefun-band" tabindex="-1"><a href="https://www.lefunsmart.com/collections/smartwatches" target="_blank" rel="noreferrer">Lefun Band</a> <a class="header-anchor" href="#lefun-band" aria-label="Permalink to &quot;[Lefun Band](https://www.lefunsmart.com/collections/smartwatches) {#lefun-band}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Lefun Band</p></div><p>L&#39;integrazione della LeFun band è stata una prima implementazione per smartband, da usare preferibilmente in mmol/l.<br> A meno che tu non abbia ancora una band LeFun W3, F3, F3S, F11 o F12, oggi non è più di alcuna utilità.</p><h3 id="miband" tabindex="-1"><a href="./miband.html">MiBand</a> <a class="header-anchor" href="#miband" aria-label="Permalink to &quot;[MiBand](./miband) {#miband}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">MiBand</p></div><p>L&#39;integrazione MiBand è il risultato dell&#39;enorme lavoro di <a href="https://bigdigital.home.blog/" target="_blank" rel="noreferrer">Artem</a>.<br> Molti smartwatch e smartband sono ora supportati tramite l&#39;app compagno WatchDrip+.</p><div class="info custom-block"><p class="custom-block-title">Disattiva MiBand in xDrip se usi WatchDrip+</p><div class="admonition xdripitem"><p class="admonition-title">Usa MiBand <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div></div><h2 id="smartwatch-sensors" tabindex="-1">Sensori dello smartwatch <a class="header-anchor" href="#smartwatch-sensors" aria-label="Permalink to &quot;Sensori dello smartwatch {#smartwatch-sensors}&quot;">​</a></h2><p>xDrip può usare i sensori degli smartwatch supportati.</p><div class="admonition xdripitem"><p class="admonition-title">Usa dati sensori di salute <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>xDrip può chiedere l&#39;attivazione del sensore del battito cardiaco e puoi rendere più uniforme quel grafico.</p><div class="admonition xdripitem"><p class="admonition-title">Cardiofrequenzimetro <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>Quando disponibili, puoi far raccogliere a xDrip dati sulla salute come frequenza cardiaca e passi.</p><p>Nella schermata principale compariranno due icone aggiuntive e, se attivate, le relative rappresentazioni grafiche:</p><ol><li>Un grafico blu scuro per la frequenza cardiaca</li><li>Una linea a nuvola azzurro chiaro per i passi</li></ol><img src="'+i+'" style="zoom:75%;"><h2 id="other-smartwatches" tabindex="-1">Altri smartwatch <a class="header-anchor" href="#other-smartwatches" aria-label="Permalink to &quot;Altri smartwatch {#other-smartwatches}&quot;">​</a></h2><p>Altri smartwatch e dispositivi possono ricevere dati da xDrip anche se non sono integrati direttamente nell&#39;app.</p><div class="info custom-block"><p class="custom-block-title">Info</p><p>Perché xDrip invii i dati devi attivare il <a href="./../use/interapp.html#web-service">web service</a> di xDrip.</p></div><h3 id="android-wear" tabindex="-1">Android Wear <a class="header-anchor" href="#android-wear" aria-label="Permalink to &quot;Android Wear {#android-wear}&quot;">​</a></h3><p><a href="https://github.com/pachi81/GlucoDataHandler" target="_blank" rel="noreferrer">GlucoDataHandler</a> accetta xDrip come sorgente dati. L&#39;app è disponibile nel <a href="https://play.google.com/store/apps/details?id=de.michelinside.glucodatahandler" target="_blank" rel="noreferrer">Google Play store</a>.</p><h3 id="android-auto" tabindex="-1">Android Auto <a class="header-anchor" href="#android-auto" aria-label="Permalink to &quot;Android Auto {#android-auto}&quot;">​</a></h3><p><a href="https://github.com/pachi81/GlucoDataAuto" target="_blank" rel="noreferrer">GlucoDataAuto</a> è l&#39;estensione Android Auto di GlucoDataHandler.</p><h3 id="fitbit" tabindex="-1">Fitbit <a class="header-anchor" href="#fitbit" aria-label="Permalink to &quot;Fitbit {#fitbit}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Google sta dismettendo Sense/Ionic/Versa</p><p>Tieni presente che questi prodotti arriveranno a fine vita nel prossimo futuro.</p></div><div class="warning custom-block"><p class="custom-block-title">Non disponibile per gli utenti UE</p><p>Google ha <a href="https://support.google.com/fitbit/answer/14237121?hl=en" target="_blank" rel="noreferrer">rimosso</a> questa possibilità da giugno 2024. I quadranti già installati non sono interessati, ma i nuovi utenti non possono più installare quadranti personalizzati. Come soluzione alternativa devi usare una VPN.</p></div><div class="warning custom-block"><p class="custom-block-title">Android 9 e precedenti</p><p>Gli utenti Android con una versione inferiore alla 10 devono riportare l&#39;app Fitbit a una versione precedente, come la 3.58, e disattivare gli aggiornamenti automatici. La trovi su <a href="https://fitbit.en.aptoide.com/versions" target="_blank" rel="noreferrer">Aptoide</a> e su altri server che ospitano apk.</p></div><h5 id="glance" tabindex="-1"><a href="https://gallery.fitbit.com/details/7b5d9822-7e8e-41f9-a2a7-e823548c001c" target="_blank" rel="noreferrer">Glance</a> <a class="header-anchor" href="#glance" aria-label="Permalink to &quot;[Glance](https://gallery.fitbit.com/details/7b5d9822-7e8e-41f9-a2a7-e823548c001c) {#glance}&quot;">​</a></h5><p>Ionic/Sense/Versa/Versa 2/Versa 3/Versa 4/Versa Lite</p><p><a href="https://glancewatchface.com/" target="_blank" rel="noreferrer">Sito web</a></p><h5 id="sentinel" tabindex="-1"><a href="https://gallery.fitbit.com/developer/b50ac7f5-b932-441a-be18-e258b17c736b" target="_blank" rel="noreferrer">Sentinel</a> <a class="header-anchor" href="#sentinel" aria-label="Permalink to &quot;[Sentinel](https://gallery.fitbit.com/developer/b50ac7f5-b932-441a-be18-e258b17c736b) {#sentinel}&quot;">​</a></h5><p>Sentinel Elite per Sense/Versa 3<br> Sentinel Pro per Ionic/Versa/Versa 2/Versa Lite</p><p>Gruppo Facebook: <a href="https://www.facebook.com/groups/3185325128159614" target="_blank" rel="noreferrer">Sentinel</a></p><h5 id="marclock" tabindex="-1"><a href="https://gallery.fitbit.com/details/9eacf714-5b23-40c8-9621-ded74bd9edf9" target="_blank" rel="noreferrer">Marclock</a> <a class="header-anchor" href="#marclock" aria-label="Permalink to &quot;[Marclock](https://gallery.fitbit.com/details/9eacf714-5b23-40c8-9621-ded74bd9edf9) {#marclock}&quot;">​</a></h5><p>Ionic/Sense/Versa/Versa 2/Versa Lite</p><p><a href="https://github.com/cramis1/Marclock-with-CGM-weather/blob/master/README.md" target="_blank" rel="noreferrer">Istruzioni</a></p><h5 id="analog-cgm" tabindex="-1"><a href="https://gallery.fitbit.com/details/4d7b46b1-aaba-49b4-aa10-183321014dd3" target="_blank" rel="noreferrer">Analog CGM</a> <a class="header-anchor" href="#analog-cgm" aria-label="Permalink to &quot;[Analog CGM](https://gallery.fitbit.com/details/4d7b46b1-aaba-49b4-aa10-183321014dd3) {#analog-cgm}&quot;">​</a></h5><h5 id="orbits-ns" tabindex="-1"><a href="https://gallery.fitbit.com/details/44de5c81-b77c-4f90-baa8-38f3e3d28695" target="_blank" rel="noreferrer">Orbits NS</a> <a class="header-anchor" href="#orbits-ns" aria-label="Permalink to &quot;[Orbits NS](https://gallery.fitbit.com/details/44de5c81-b77c-4f90-baa8-38f3e3d28695) {#orbits-ns}&quot;">​</a></h5><h5 id="radial-cgm" tabindex="-1"><a href="https://gallery.fitbit.com/details/0173730e-5381-4495-bc6e-6ec93c8df029" target="_blank" rel="noreferrer">Radial CGM</a> <a class="header-anchor" href="#radial-cgm" aria-label="Permalink to &quot;[Radial CGM](https://gallery.fitbit.com/details/0173730e-5381-4495-bc6e-6ec93c8df029) {#radial-cgm}&quot;">​</a></h5><p>Ionic/Versa/Versa 2/Versa Lite/Versa 3/Sense</p><h3 id="samsung-gear" tabindex="-1">Samsung Gear <a class="header-anchor" href="#samsung-gear" aria-label="Permalink to &quot;Samsung Gear {#samsung-gear}&quot;">​</a></h3><p><a href="https://play.google.com/store/apps/details?id=sk.trupici.g_watch" target="_blank" rel="noreferrer">G-Watch</a> è il modo più semplice per farlo. Vedi la <a href="https://github.com/trupici/G-Watch-Wear/wiki" target="_blank" rel="noreferrer">wiki</a>.</p><p>Puoi anche usare <a href="https://github.com/FreDiabetics/xDrip--Tasker-Tizen-Watchface-Integration/blob/master/README.md" target="_blank" rel="noreferrer">Tasker</a> per mostrare i dati di xDrip sul tuo orologio Samsung Gear.</p><h3 id="garmin" tabindex="-1">Garmin <a class="header-anchor" href="#garmin" aria-label="Permalink to &quot;Garmin {#garmin}&quot;">​</a></h3><p>Sono disponibili molti quadranti Garmin: verifica che il tuo modello sia supportato.</p><p>Di <a href="https://apps.garmin.com/en-US/developer/e985e9ec-bcf6-4aef-bfe9-77c1c93fc854/apps" target="_blank" rel="noreferrer">Horsetooth</a></p><p>Di <a href="https://apps.garmin.com/en-US/developer/f9420c47-810f-47ac-a7dd-9fa7b8ecd22d/apps" target="_blank" rel="noreferrer">andreas-may</a></p><p>Di <a href="https://apps.garmin.com/en-US/developer/b2d30711-2708-4f3a-8e83-009c16d07081/apps" target="_blank" rel="noreferrer">John_</a></p><p>Di <a href="https://apps.garmin.com/en-US/developer/b61690c3-5e5c-4c4e-afe9-434db16542a9/apps" target="_blank" rel="noreferrer">Roboleo1010</a></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',68)])])}const z=o(c,[["render",d]]);export{w as __pageData,z as default};
